new:
for entity in players {
    let Some(component) = world.get_component_mut::<TimelinePlayerComponent>(entity) else {
        continue;
    };
    if component.autoplay && component.player.state() == TimelinePlayState::Stopped {
        component.player.play();
    }
    let timeline = Arc::clone(&component.timeline);
    let evaluation = component.player.advance(&timeline, delta_seconds);
    let generation = component.player.generation();
    let force_animation_seek =
        component.tokens.get(ANIMATION_GENERATION_TOKEN) != Some(generation);
    component
        .tokens
        .set(ANIMATION_GENERATION_TOKEN, generation);
    let player_state = component.player.state();
    let player_rate = component.player.rate();

    apply_animation_evaluation(
        entity,
        &timeline,
        &evaluation,
        player_state,
        player_rate,
        force_animation_seek,
        world,
        bindings,
        diagnostics,
    );
    apply_evaluation(
        entity,
        &evaluation,
        world,
        bindings,
        camera_override,
        events,
        diagnostics,
    );
}
